import boto3
from botocore.exceptions import ClientError
import json


def fetch_api_key(secret_id: str, key_name: str = "API_KEY") -> str:
    client = boto3.client("secretsmanager")
    try:
        response = client.get_secret_value(SecretId=secret_id)
        secret_string = response.get("SecretString")
        if not secret_string:
            raise ValueError("Secret does not contain a string payload")
        secret_dict = json.loads(secret_string)
        api_key = secret_dict.get(key_name)
        if api_key is None:
            raise KeyError(f"'{key_name}' not found in secret '{secret_id}'")
        return api_key
    except ClientError as e:
        error_code = e.response["Error"]["Code"]
        if error_code == "ResourceNotFoundException":
            raise RuntimeError(f"Secret '{secret_id}' not found in AWS Secrets Manager") from e
        raise RuntimeError(f"Failed to fetch secret from AWS Secrets Manager: {error_code}") from e
